using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var tools = new ResearchTools();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the WebSearch tool to find relevant information (make multiple searches with different queries).
        2. Use the SaveNote tool to record key findings as you go.
        3. After gathering enough information, use the GetNotes tool to review all saved notes.
        4. Provide a comprehensive summary of your research to the user.
        Be thorough — search for multiple aspects of the topic.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking.",
    tools: [AIFunctionFactory.Create(tools.WebSearch),
            AIFunctionFactory.Create(tools.SaveNote),
            AIFunctionFactory.Create(tools.GetNotes)]);

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync($"Research this topic thoroughly: {topic}", session, runOptions);

var assistantMessage = response.Messages
    .LastOrDefault(m => m.Role == ChatRole.Assistant && m.Text is not null);

Console.WriteLine("=== Research Summary ===\n");
Console.WriteLine(assistantMessage?.Text ?? "No summary was produced.");
Console.WriteLine($"\n--- Notes collected: {tools.NoteCount} ---");

/// <summary>Tools available to the research agent.</summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a query. Returns search result snippets.")]
    public async Task<string> WebSearch(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var html = await _httpClient.SendAsync(request)
                .ContinueWith(t => t.Result.Content.ReadAsStringAsync()).Unwrap();

            var snippets = ExtractSnippets(html);
            return snippets.Length > 0
                ? string.Join("\n\n", snippets)
                : $"No results found for '{query}'.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note with a title and content for later reference.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Content of the note")] string content)
    {
        Console.WriteLine($"  📝 Note saved: {title}");
        _notes.Add($"## {title}\n{content}");
        return $"Note '{title}' saved successfully.";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        Console.WriteLine($"  📋 Retrieving {_notes.Count} note(s)");
        return string.Join("\n\n---\n\n", _notes);
    }

    private static string[] ExtractSnippets(string html)
    {
        var results = new List<string>();
        var searchStart = 0;
        // Extract text from DuckDuckGo result snippets (class="result__snippet")
        while (results.Count < 6)
        {
            var marker = "class=\"result__snippet\"";
            var idx = html.IndexOf(marker, searchStart, StringComparison.Ordinal);
            if (idx < 0) break;

            var tagClose = html.IndexOf('>', idx + marker.Length);
            if (tagClose < 0) break;

            var endTag = html.IndexOf('<', tagClose + 1);
            if (endTag < 0) break;

            var snippet = html[(tagClose + 1)..endTag].Trim();
            snippet = System.Net.WebUtility.HtmlDecode(snippet);
            if (snippet.Length > 20)
                results.Add(snippet);

            searchStart = endTag;
        }

        return [.. results];
    }
}

